description:
Add GNSS-synchronized hopping functions to Zephyr LICHEN subsystem.

## Files
- lichen/subsys/lichen/link/sync_hop.c
- lichen/subsys/lichen/link/include/lichen/sync_hop.h

## Header (sync_hop.h)
```c
#ifndef LICHEN_SYNC_HOP_H
#define LICHEN_SYNC_HOP_H

#include <stdint.h>

/**
 * @brief Calculate hop channel from SFN using LICHEN hash.
 * @param sfn Superframe number
 * @param seed Hopping seed
 * @param n_channels Number of channels (minimum 3)
 * @return Channel in range [1, n_channels]
 */
uint8_t lichen_sync_hop_channel(uint32_t sfn, uint32_t seed, uint8_t n_channels);

/**
 * @brief Derive SFN from unix timestamp.
 * @param unix_time_ms Unix time in milliseconds
 * @return Superframe number
 */
uint32_t lichen_sfn_from_unix_ms(uint64_t unix_time_ms);

#endif /* LICHEN_SYNC_HOP_H */
```

## Implementation (sync_hop.c)
```c
#include <lichen/sync_hop.h>
#include <lichen/l2/lichen_util.h>

#define EPOCH_BASE_MS 1704067200000ULL  /* 2024-01-01 00:00:00 UTC */

uint8_t lichen_sync_hop_channel(uint32_t sfn, uint32_t seed, uint8_t n_channels)
{
    uint8_t data[8];
    uint32_t hash;

    /* Pack seed (LE) || sfn (LE) */
    data[0] = (uint8_t)(seed);
    data[1] = (uint8_t)(seed >> 8);
    data[2] = (uint8_t)(seed >> 16);
    data[3] = (uint8_t)(seed >> 24);
    data[4] = (uint8_t)(sfn);
    data[5] = (uint8_t)(sfn >> 8);
    data[6] = (uint8_t)(sfn >> 16);
    data[7] = (uint8_t)(sfn >> 24);

    hash = lichen_hash_32(data, sizeof(data));

    if (n_channels < 3) {
        n_channels = 3;
    }

    return 1 + (hash % n_channels);
}

uint32_t lichen_sfn_from_unix_ms(uint64_t unix_time_ms)
{
    uint64_t superframe_ms = CONFIG_LICHEN_SYNC_HOP_SUPERFRAME_MS;
    return (uint32_t)((unix_time_ms - EPOCH_BASE_MS) / superframe_ms);
}
```

## Build Integration
- Add to CMakeLists.txt with CONFIG_LICHEN_SYNC_HOP guard
- Use canonical lichen_hash_32 from l2/lichen_util.h
